node -e "
const Database = require('better-sqlite3');
const db = new Database('.state/may.db', { readonly: true });
// Get evaluations table schema
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='evaluations'\").get();
console.log('SCHEMA:', schema?.sql);
// Sample rows
const rows = db.prepare('SELECT * FROM evaluations LIMIT 3').all();
console.log('SAMPLE:', JSON.stringify(rows, null, 2));
// Distribution
const dist = db.prepare('SELECT quality, COUNT(*) as cnt FROM evaluations GROUP BY quality ORDER BY quality').all();
console.log('QUALITY DIST:', JSON.stringify(dist));
const edist = db.prepare('SELECT efficiency, COUNT(*) as cnt FROM evaluations GROUP BY efficiency ORDER BY efficiency').all();
console.log('EFFICIENCY DIST:', JSON.stringify(edist));
const vdist = db.prepare('SELECT verdict, COUNT(*) as cnt FROM evaluations GROUP BY verdict ORDER BY verdict').all();
console.log('VERDICT DIST:', JSON.stringify(vdist));
db.close();
" 2>&1

